-- Product Learning Sync checked: observed status transitions, verified money, scoped whole aggregates before paging.
create table public.sv_report_coverage(singleton boolean primary key default true check(singleton),recorded_from timestamptz not null);insert into public.sv_report_coverage values(true,statement_timestamp());
create table public.sv_business_outcomes(company_id uuid not null references public.sv_companies(id),id uuid not null default gen_random_uuid(),source_key text not null,source_version text not null,kind text not null check(kind in('confirmed','cancelled','attended','payment','refund','purchase')),brand_id text not null,customer_id text not null,product text not null check(product in('crm','pos')),occurred_at timestamptz,observed_at timestamptz not null default statement_timestamp(),amount_cents bigint,currency text not null default 'HKD',baseline boolean not null default false,detail jsonb not null,primary key(company_id,id),unique(company_id,source_key,source_version,kind));
create index sv_business_outcomes_period on public.sv_business_outcomes(company_id,occurred_at,id);create index sv_business_outcomes_customer on public.sv_business_outcomes(company_id,brand_id,customer_id,observed_at,id);
create table public.sv_campaign_costs(company_id uuid not null,campaign_id uuid not null,amount_cents bigint not null check(amount_cents between 0 and 100000000000),currency text not null check(currency='HKD'),source text not null check(length(btrim(source))between 1 and 500),revision bigint not null default 1,recorded_by uuid not null,primary key(company_id,campaign_id),foreign key(company_id,campaign_id)references public.sv_campaigns(company_id,id));
create function smartvolt_private.outcome_booking()returns trigger language plpgsql security invoker set search_path=''as $$declare product text;source text;version text;brand text;customer text;k text;details jsonb;begin
 if tg_table_name='sv_pos_appointments'then product='pos';source='pos:'||new.id;version=new.workspace_revision::text;brand=new.brand_id;customer=new.contact_id;details=jsonb_build_object('appointmentId',new.id,'scheduledAt',to_timestamp(new.starts_at::double precision/1000));
 else product='crm';source='crm:'||new.id;version=new.revision::text;brand=new.brand_id;customer=new.customer_id;details=jsonb_build_object('requestId',new.id,'provider',new.provider,'threadId',new.thread_id,'scheduledAt',new.desired_at);end if;
 if tg_op='UPDATE'and new.status=old.status then return new;end if;
 k=case when new.status in('confirmed','linked')then 'confirmed'when new.status in('checked_in','completed')then 'attended'when new.status in('cancelled','no_show')then 'cancelled'end;
 if k is null then return new;end if;
 insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,occurred_at,detail)values(new.company_id,source,version,k,brand,customer,product,statement_timestamp(),details)on conflict do nothing;return new;
end;$$;
create function smartvolt_private.outcome_money()returns trigger language plpgsql security invoker set search_path=''as $$declare o public.sv_pos_orders;k text;net bigint;begin
 select *into strict o from public.sv_pos_orders where company_id=new.company_id and id=new.order_id;
 k=case when tg_table_name='sv_pos_payments'then 'payment'else 'refund'end;
 insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,occurred_at,amount_cents,detail)values(new.company_id,k||':'||new.id,'1',k,o.brand_id,o.contact_id,'pos',to_timestamp(new.occurred_at::double precision/1000),new.amount_cents,jsonb_build_object('orderId',o.id,'receiptId',new.id,'source',new.source))on conflict do nothing;
 select coalesce((select sum(amount_cents)from public.sv_pos_payments where company_id=o.company_id and order_id=o.id),0)-coalesce((select sum(amount_cents)from public.sv_pos_refunds where company_id=o.company_id and order_id=o.id),0)into net;
 if k='payment'and not o.voided and o.total_cents>0 and net>=o.total_cents then
 insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,occurred_at,amount_cents,detail)values(new.company_id,'purchase:'||o.id,'1','purchase',o.brand_id,o.contact_id,'pos',to_timestamp(new.occurred_at::double precision/1000),o.total_cents,jsonb_build_object('orderId',o.id,'source','manual_verified','completingReceipt',new.id))on conflict do nothing;end if;return new;
end;$$;
create trigger sv_outcome_crm_booking after insert or update on public.sv_booking_requests for each row execute function smartvolt_private.outcome_booking();
create trigger sv_outcome_pos_booking after insert or update on public.sv_pos_appointments for each row execute function smartvolt_private.outcome_booking();
create trigger sv_outcome_payment after insert on public.sv_pos_payments for each row execute function smartvolt_private.outcome_money();
create trigger sv_outcome_refund after insert on public.sv_pos_refunds for each row execute function smartvolt_private.outcome_money();
-- Baseline status has no invented confirmation/check-in time. Historical receipt times remain authoritative.
insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,baseline,detail)
 select company_id,'crm:'||id,revision::text,case when status in('confirmed','linked')then 'confirmed'else 'cancelled'end,brand_id,customer_id,'crm',true,jsonb_build_object('requestId',id,'provider',provider,'threadId',thread_id,'scheduledAt',desired_at)from public.sv_booking_requests where status in('confirmed','linked','cancelled');
insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,baseline,detail)
 select company_id,'pos:'||id,workspace_revision::text,case when status='confirmed'then 'confirmed'when status in('checked_in','completed')then 'attended'else 'cancelled'end,brand_id,contact_id,'pos',true,jsonb_build_object('appointmentId',id,'scheduledAt',to_timestamp(starts_at::double precision/1000))from public.sv_pos_appointments where status in('confirmed','checked_in','completed','cancelled','no_show');
insert into public.sv_business_outcomes(company_id,source_key,source_version,kind,brand_id,customer_id,product,baseline,occurred_at,amount_cents,detail)
 select p.company_id,'payment:'||p.id,'1','payment',o.brand_id,o.contact_id,'pos',true,to_timestamp(p.occurred_at::double precision/1000),p.amount_cents,jsonb_build_object('orderId',o.id,'receiptId',p.id,'source',p.source)from public.sv_pos_payments p join public.sv_pos_orders o on o.company_id=p.company_id and o.id=p.order_id
 union all select p.company_id,'refund:'||p.id,'1','refund',o.brand_id,o.contact_id,'pos',true,to_timestamp(p.occurred_at::double precision/1000),p.amount_cents,jsonb_build_object('orderId',o.id,'receiptId',p.id,'source',p.source)from public.sv_pos_refunds p join public.sv_pos_orders o on o.company_id=p.company_id and o.id=p.order_id;
create view smartvolt_private.report_inquiries with(security_invoker=true)as
 select i.company_id,i.brand_id,i.customer_id,i.provider||':'||i.thread_id key,i.channel,i.created_at from smartvolt_private.ops_inquiries i
 union all select company_id,brand_id,customer_id,'website:'||source_id,'website',source_created_at from public.sv_sales_enquiries;
create view smartvolt_private.report_outcomes with(security_invoker=true)as
 select o.*,coalesce(case when o.source_key like 'crm:%'then(select 'pos:'||r.pos_appointment_id from public.sv_booking_requests r where r.company_id=o.company_id and 'crm:'||r.id=o.source_key and r.pos_appointment_id is not null)end,o.source_key)booking_key
 from public.sv_business_outcomes o;
create view smartvolt_private.report_replies with(security_invoker=true)as
 select m.company_id,l.brand_id,l.customer_id,m.created_at,m.conversation_id thread_id,'whatsapp'provider from public.sv_wa_messages m join public.sv_customer_threads l on l.company_id=m.company_id and l.provider='whatsapp'and l.thread_id=m.conversation_id where m.direction='incoming'
 union all select m.company_id,l.brand_id,l.customer_id,m.created_at,m.thread_id,'meta'from public.sv_meta_messages m join public.sv_customer_threads l on l.company_id=m.company_id and l.provider='meta'and l.thread_id=m.thread_id where m.direction='inbound';
create function smartvolt_private.report_touch(p_company uuid,p_customer text,p_brand text,p_at timestamptz,p_as_of timestamptz)returns uuid language sql stable security invoker set search_path=''as $$
 select j.source_id from public.sv_delivery_jobs j where j.company_id=p_company and j.customer_id=p_customer and j.brand_id=p_brand and j.origin='campaign'and j.attempted_at<=p_at and j.attempted_at>p_at-interval '7 days'and exists(select 1 from public.sv_delivery_events e where e.company_id=j.company_id and e.job_id=j.id and e.kind in('accepted','sent','delivered','read')and e.created_at<=least(p_as_of,p_at))order by j.attempted_at desc,j.id desc limit 1
$$;
create function public.sv_reports_read(p_company uuid,p_actor uuid,p_from timestamptz,p_to timestamptz,p_as_of timestamptz,p_brand text default null,p_mode text default 'period',p_before timestamptz default null,p_id uuid default null,p_event_before timestamptz default null,p_event_id uuid default null)returns jsonb language plpgsql security invoker set search_path=''as $$
declare result jsonb;has_pos boolean;begin
 perform public.sv_authorize(p_company,p_actor,'crm',false,true,p_brand);has_pos=smartvolt_private.member_has_product(p_company,p_actor,'pos');
 if p_from is null or p_to is null or p_as_of is null or p_to<=p_from or p_to-p_from>interval '367 days'or p_as_of>statement_timestamp()+interval '1 minute'or p_mode not in('period','cohort')then raise exception 'invalid_period';end if;
 with inquiries as materialized(select i.*from smartvolt_private.report_inquiries i where i.company_id=p_company and i.created_at<=p_as_of and(p_brand is null or i.brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,i.brand_id)),
 cohort as materialized(select brand_id,customer_id,min(created_at)first_seen from inquiries group by brand_id,customer_id having min(created_at)>=p_from and min(created_at)<p_to),
 outcomes as materialized(select o.*from smartvolt_private.report_outcomes o where o.company_id=p_company and(p_brand is null or o.brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,o.brand_id)and(o.product='crm'or has_pos)and o.observed_at<=p_as_of and coalesce(o.occurred_at,o.observed_at)<=p_as_of),
 selected as materialized(select o.*from outcomes o where(p_mode='period'and o.occurred_at>=p_from and o.occurred_at<p_to)or(p_mode='cohort'and exists(select 1 from cohort c where c.brand_id=o.brand_id and c.customer_id=o.customer_id))),
 bookings as materialized(select distinct booking_key from selected s where s.kind='confirmed'and not exists(select 1 from outcomes x where x.booking_key=s.booking_key and x.kind='cancelled'and x.observed_at>s.observed_at)),
 campaign_rows as materialized(select c.*from public.sv_campaigns c where c.company_id=p_company and(p_brand is null or c.brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,c.brand_id)and c.created_at>=p_from and c.created_at<p_to),
 associations as materialized(select s.id,s.kind,s.amount_cents,smartvolt_private.report_touch(p_company,s.customer_id,s.brand_id,s.occurred_at,p_as_of)campaign_id from selected s where not s.baseline),
 performance as materialized(select c.id,c.name,c.created_at,
 (select count(*)from public.sv_delivery_jobs j where j.company_id=p_company and j.source_id=c.id and j.origin='campaign')recipients,
 (select count(*)from public.sv_delivery_jobs j where j.company_id=p_company and j.source_id=c.id and j.origin='campaign'and exists(select 1 from public.sv_delivery_events e where e.company_id=p_company and e.job_id=j.id and e.kind in('delivered','read')and e.created_at<=p_as_of))delivered,
 (select count(distinct(r.customer_id,r.brand_id))from smartvolt_private.report_replies r where r.company_id=p_company and r.created_at<=p_as_of and smartvolt_private.report_touch(p_company,r.customer_id,r.brand_id,r.created_at,p_as_of)=c.id)replied,
 (select count(*)from public.sv_preference_events e where e.company_id=p_company and e.brand_id=c.brand_id and not e.allowed and e.purpose=c.purpose and e.created_at<=p_as_of and smartvolt_private.report_touch(p_company,e.customer_id,e.brand_id,e.created_at,p_as_of)=c.id)optouts,
 (select count(distinct s.booking_key)from selected s join associations a on a.id=s.id where a.campaign_id=c.id and s.kind='confirmed')confirmed,
 (select count(distinct s.booking_key)from selected s join associations a on a.id=s.id where a.campaign_id=c.id and s.kind='attended')attended,
 case when has_pos then coalesce((select sum(case when a.kind='refund'then -a.amount_cents else a.amount_cents end)from associations a where a.campaign_id=c.id and a.kind in('payment','refund')),0)end net_cents,
 case when has_pos then cost.amount_cents end cost_cents,case when has_pos then cost.source end cost_source,case when has_pos then coalesce(cost.revision,0)end cost_revision
 from campaign_rows c left join public.sv_campaign_costs cost on cost.company_id=c.company_id and cost.campaign_id=c.id)
 select jsonb_build_object('coverageFrom',(select recorded_from from public.sv_report_coverage where singleton),'hasPos',has_pos,
 'brands',coalesce((select jsonb_agg(jsonb_build_object('id',b->>'id','name',b->>'name'))from public.sv_workspaces w,jsonb_array_elements(w.payload#>'{scope,brands}')b where w.company_id=p_company and smartvolt_private.member_brand_allowed(p_company,p_actor,b->>'id')),'[]'),
 'metrics',jsonb_build_object('inquiries',(select count(*)from inquiries where created_at>=p_from and created_at<p_to),'customers',(select count(*)from cohort),'confirmed',(select count(*)from bookings),'attended',(select count(distinct booking_key)from selected where kind='attended'),'baselineUnknown',(select count(*)from outcomes where baseline and occurred_at is null),'receiptsCents',case when has_pos then coalesce((select sum(amount_cents)from selected where kind='payment'),0)end,'refundsCents',case when has_pos then coalesce((select sum(amount_cents)from selected where kind='refund'),0)end,'unassociated',(select count(*)from selected s where s.kind in('confirmed','attended','payment')and not exists(select 1 from associations a where a.id=s.id and a.campaign_id is not null))),
 'trend',coalesce((select jsonb_agg(t order by t.day)from(select to_char(d,'YYYY-MM-DD')as day,(select count(*)from inquiries i where(i.created_at at time zone 'Asia/Hong_Kong')::date=d::date)inquiries,(select count(distinct s.booking_key)from selected s where s.kind='confirmed'and(s.occurred_at at time zone 'Asia/Hong_Kong')::date=d::date)confirmed from generate_series((p_from at time zone 'Asia/Hong_Kong')::date::timestamp,((p_to-interval '1 second')at time zone 'Asia/Hong_Kong')::date::timestamp,interval '1 day')d)t),'[]'),
 'channels',coalesce((select jsonb_agg(x order by x.channel)from(select channel,count(*)inquiries from inquiries where created_at>=p_from and created_at<p_to group by channel)x),'[]'),
 'staff',coalesce((select jsonb_agg(x order by x.replies desc,x.id)from(select e.human_actor id,max(e.human_name)name,count(*)replies,round(avg(smartvolt_private.work_minutes(e.started_at,e.first_human_at,e.policy)),1)response_minutes from public.sv_sla_episodes e where e.company_id=p_company and e.first_human_at>=p_from and e.first_human_at<least(p_to,p_as_of)and(p_brand is null or e.brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,e.brand_id)group by e.human_actor)x),'[]'),
 'events',coalesce((select jsonb_agg(x order by x.observed_at desc,x.id desc)from(select id,source_key,source_version,kind,occurred_at,observed_at,amount_cents,baseline,product from selected where p_event_before is null or(observed_at,id)<(p_event_before,p_event_id)order by observed_at desc,id desc limit 51)x),'[]'),
 'campaignTotal',(select count(*)from performance),'campaigns',coalesce((select jsonb_agg(x order by x.created_at desc,x.id desc)from(select *from performance where p_before is null or(created_at,id)<(p_before,p_id)order by created_at desc,id desc limit 31)x),'[]'))into result;return result;
end;$$;
create function public.sv_campaign_cost_action(p_company uuid,p_actor uuid,p_command uuid,p_id uuid,p_revision bigint,p_amount bigint,p_source text)returns jsonb language plpgsql security invoker set search_path=''as $$declare brand text;r jsonb;data jsonb:=jsonb_build_object('id',p_id,'revision',p_revision,'amount',p_amount,'source',p_source);begin
 select brand_id into strict brand from public.sv_campaigns where company_id=p_company and id=p_id;perform public.sv_authorize(p_company,p_actor,'crm',true,true,brand);perform public.sv_authorize(p_company,p_actor,'pos',true,true,brand);
 r=smartvolt_private.action_replay(p_company,p_actor,p_command,'campaign-cost',data);if r is not null then return r;end if;
 perform pg_advisory_xact_lock(hashtextextended('campaign-cost:'||p_company||':'||p_id,0));
 if coalesce((select revision from public.sv_campaign_costs where company_id=p_company and campaign_id=p_id for update),0)<>p_revision then raise exception 'revision_conflict';end if;
 insert into public.sv_campaign_costs(company_id,campaign_id,amount_cents,currency,source,recorded_by)values(p_company,p_id,p_amount,'HKD',p_source,p_actor)on conflict(company_id,campaign_id)do update set amount_cents=excluded.amount_cents,source=excluded.source,revision=sv_campaign_costs.revision+1;
 r='{"saved":true}';insert into public.sv_action_receipts(company_id,command_id,actor_id,kind,data,result)values(p_company,p_command,p_actor,'campaign-cost',data,r);return r;end;$$;
do $$declare t text;f record;begin
 foreach t in array array['sv_report_coverage','sv_business_outcomes','sv_campaign_costs']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select,insert,update on public.%I to service_role',t);end loop;
 revoke insert,update on public.sv_report_coverage from service_role;revoke update on public.sv_business_outcomes from service_role;
 for f in select oid::regprocedure signature from pg_proc where pronamespace in('public'::regnamespace,'smartvolt_private'::regnamespace)and proname in('outcome_booking','outcome_money','report_touch','sv_reports_read','sv_campaign_cost_action')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end;$$;
revoke all on smartvolt_private.report_inquiries,smartvolt_private.report_outcomes,smartvolt_private.report_replies from public,anon,authenticated;grant select on smartvolt_private.report_inquiries,smartvolt_private.report_outcomes,smartvolt_private.report_replies to service_role;
create trigger sv_business_outcomes_immutable before update or delete on public.sv_business_outcomes for each row execute function smartvolt_private.wa_reject_rewrite();create trigger sv_business_outcomes_no_truncate before truncate on public.sv_business_outcomes for each statement execute function smartvolt_private.wa_reject_rewrite();
